-- Patch for already-seeded environments only.
--
-- Syncs the Livestock Details (Animal) section's section_ui_schema to the
-- canonical definition in g2p_register_sections.sql. The seed only INSERTs and
-- never touches an existing row, so any environment seeded before a change to
-- that line keeps the old dialog forever; this file re-applies the whole
-- schema by section_id, regardless of what the stored JSON looked like.
--
-- Why now: the Breed column was a species-cascaded dropdown ("dependsOn" +
-- "widget-cascade"). The official staff-ui does not wire cascades inside
-- dialog-table pop-ups (the listener never fires), so Breed always rendered
-- EMPTY while being required -> no animal could be added from the UI. Breed is
-- now the plain LIVESTOCK_BREED_NAME list; the breed<->species rule is enforced
-- server-side instead (validate_belongs_to_species in
-- register_domain/services/domain_validation_utils.py).
--
-- 2026-09-21: the ear_tag_id / secondary_identifier / quantity / date_of_birth
-- show/hide/require actions (species__raw.* conditions, unsupported by the stock
-- staff-ui) are gone — livestock-dialog-overlay.js applies that behaviour instead —
-- and the "state" (Status) column is removed from the dialog.
--
-- Keep this file in sync with line "livestock_animal_details_section_01" of
-- g2p_register_sections.sql (it was generated from it). Runs after the other
-- patch_ls_animal_details_*.sql files by name order, so the final state is the
-- canonical schema.
UPDATE "public"."g2p_register_sections"
SET section_ui_schema = '{"panels": [{"panels": [{"widgets": [{"widget": "dialog-table", "widget-id": "ls_animal_details_table", "widget-type": "dialog-table", "widget-label": "Livestock Details", "widget-readonly": false, "widget-data-path": "041a9f79-2142-548a-a15b-a4c76fc9f6f7.records", "widget-data-columns": [{"widget": "text", "column-key": "ear_tag_id", "widget-type": "input", "widget-label": "Livestock Ear Tag", "widget-readonly": false, "widget-data-path": "ear_tag_id", "widget-required": false}, {"widget": "text", "column-key": "secondary_identifier", "widget-type": "input", "widget-label": "Secondary Identifier", "widget-readonly": false, "widget-data-path": "secondary_identifier", "widget-data-placeholder": "Flock / Batch / Hive ID (e.g. FLOCK-2026-01)", "widget-required": false}, {"widget": "select", "column-key": "species", "widget-type": "input", "widget-label": "Species", "widget-readonly": false, "widget-data-path": "species", "widget-data-source": {"type": "api", "method": "POST", "params": {"attribute_id": "LIVESTOCK_TYPE", "page_size": 500}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}, "widget-required": true}, {"widget": "select", "column-key": "breed", "widget-type": "input", "widget-label": "Breed", "widget-readonly": false, "widget-data-path": "breed", "widget-data-source": {"type": "api", "method": "POST", "params": {"attribute_id": "LIVESTOCK_BREED_NAME", "page_size": 500}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}, "widget-required": false}, {"widget": "number", "column-key": "quantity", "widget-type": "input", "widget-label": "Quantity (Head Count)", "widget-readonly": false, "widget-data-path": "quantity", "widget-data-format": {"textAlign": "right"}, "widget-required": false}, {"widget": "number", "column-key": "weight", "widget-type": "input", "widget-label": "Weight (kg)", "widget-readonly": false, "widget-data-path": "weight", "widget-data-format": {"textAlign": "right", "numericType": "decimal", "thousandSeparator": ","}}, {"widget": "date", "column-key": "date_of_birth", "widget-type": "input", "widget-label": "Date of Birth", "widget-readonly": false, "widget-data-path": "date_of_birth", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker", "dateConstraint": "any"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-required": false}, {"widget": "text", "column-key": "age", "widget-type": "input", "widget-label": "Age", "widget-readonly": true, "widget-data-path": "age", "widget-age-from-date": {"baseField": "date_of_birth"}}, {"widget": "select", "column-key": "gender", "widget-type": "input", "widget-label": "Sex", "widget-readonly": false, "widget-data-path": "gender", "widget-data-source": {"type": "static", "options": [{"label": "MALE", "value": "MALE"}, {"label": "FEMALE", "value": "FEMALE"}, {"label": "Mixed / Not Applicable", "value": "MIXED"}]}, "widget-required": true}, {"widget": "select", "column-key": "health_status", "widget-type": "input", "widget-label": "Health Status", "widget-readonly": false, "widget-data-path": "health_status", "widget-data-source": {"type": "static", "options": [{"label": "HEALTHY", "value": "HEALTHY"}, {"label": "SICK", "value": "SICK"}, {"label": "QUARANTINED", "value": "QUARANTINED"}, {"label": "DECEASED", "value": "DECEASED"}]}, "widget-required": true, "widget-badge-colors": {"HEALTHY": "green", "SICK": "yellow", "QUARANTINED": "orange", "DECEASED": "red"}}, {"widget": "select", "column-key": "vaccination_status", "widget-type": "input", "widget-label": "Vaccination Status", "widget-readonly": false, "widget-data-path": "vaccination_status", "widget-data-source": {"type": "static", "options": [{"label": "UP_TO_DATE", "value": "UP_TO_DATE"}, {"label": "OVERDUE", "value": "OVERDUE"}, {"label": "NONE", "value": "NONE"}]}, "widget-required": true}, {"widget": "date", "column-key": "registration_date", "widget-type": "input", "widget-label": "Registration Date", "widget-readonly": false, "widget-data-path": "registration_date", "widget-data-default": "today", "widget-data-format": {"dateFormat": "DD/MM/YYYY", "inputMethod": "picker", "dateConstraint": "any"}, "widget-data-placeholder": "dd_mm_yyyy", "widget-required": true}], "widget-data-operations": {"add": true, "edit": true, "remove": true}, "widget-data-dialog-title-add": "Add Livestock Details", "widget-data-dialog-title-edit": "Edit Livestock Details"}], "panel-id": "vertical_panel_ls_animal_details_1", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_animal_details", "panel-orientation": "horizontal"}], "section-id": "livestock_animal_details_section_01", "section-title": "Livestock Details", "section-editable": true}'::jsonb
WHERE section_id = 'livestock_animal_details_section_01';
